import re

# Read the HTML page
with open('/app/resources/treasury_bulletin_1941_05_page_32.txt', 'r') as f:
    content = f.read()

# Parse using regex to find table rows
tr_pattern = r'<tr>(.*?)</tr>'
rows = re.findall(tr_pattern, content, re.DOTALL)

def extract_text(html):
    text = re.sub(r'<[^>]+>', '', html)
    return text.strip()

def parse_value(val):
    if not val or val == '-':
        return 0
    val = val.replace(',', '').strip()
    try:
        return int(float(val))
    except:
        return 0

# Check the exact values from the original HTML
print("Looking at raw cell values for Nat. Defense Series:")
for i, row in enumerate(rows):
    cells = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)
    if len(cells) >= 4:
        desc = extract_text(cells[0])

        if 'Nat. Defense' in desc:
            print(f"\nRow {i}: {desc}")
            print(f"  Col 1 (Fixed-maturity): '{extract_text(cells[1])}' -> {parse_value(extract_text(cells[1]))}")
            print(f"  Col 2 (Callable): '{extract_text(cells[2])}' -> {parse_value(extract_text(cells[2]))}")

            # Check if this security appears in both sections (maturity section)
            if len(cells) >= 8:
                print(f"  Col 5 (Fixed-maturity - maturity side): '{extract_text(cells[5])}' -> {parse_value(extract_text(cells[5]))}")
                print(f"  Col 6 (Callable - maturity side): '{extract_text(cells[6])}' -> {parse_value(extract_text(cells[6]))}")
